#include <cstdio>
#include <vector>

int main() {
    int n;
    scanf("%d", &n);
    std::vector<long long> a(n);
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);

    long long cand = a[0];
    int cnt = 0;
    for (int i = 0; i < n; ++i) {
        if (cnt == 0) { cand = a[i]; cnt = 1; }
        else if (a[i] == cand) ++cnt;
        else --cnt;
    }
    printf("%lld\n", cand);
    return 0;
}
